import { useState } from 'react';
import { JxButton } from '@jinx-ui/react';

// Из документируемого API использую только JxButton; разметка таблицы — нативная,
// оформление через токены var(--jx-*), чтобы не завязываться на неподтверждённые компоненты.

export interface TableUser {
  id: string | number;
  name: string;
  role: string;
  active: boolean;
}

export interface UsersTableProps {
  users: TableUser[];
}

const PAGE_SIZE = 10;

const cellStyle: React.CSSProperties = {
  padding: 'var(--jx-space-3) var(--jx-space-4)',
  textAlign: 'left',
  borderBottom: '1px solid var(--jx-color-border)',
};

const headStyle: React.CSSProperties = {
  ...cellStyle,
  color: 'var(--jx-color-fg-muted)',
  fontSize: 'var(--jx-font-size-sm)',
  fontWeight: 'var(--jx-font-weight-medium)',
};

function UsersTable({ users }: UsersTableProps) {
  const [page, setPage] = useState(0);

  const pageCount = Math.max(1, Math.ceil(users.length / PAGE_SIZE));
  const current = Math.min(page, pageCount - 1);
  const start = current * PAGE_SIZE;
  const rows = users.slice(start, start + PAGE_SIZE);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-4)' }}>
      <table
        style={{
          width: '100%',
          borderCollapse: 'collapse',
          color: 'var(--jx-color-fg)',
          background: 'var(--jx-color-surface)',
          border: '1px solid var(--jx-color-border)',
          borderRadius: 'var(--jx-radius-md)',
          overflow: 'hidden',
        }}
      >
        <caption style={{ position: 'absolute', width: 1, height: 1, overflow: 'hidden', clip: 'rect(0 0 0 0)' }}>
          Пользователи
        </caption>
        <thead>
          <tr>
            <th scope="col" style={headStyle}>Имя</th>
            <th scope="col" style={headStyle}>Роль</th>
            <th scope="col" style={headStyle}>Статус</th>
          </tr>
        </thead>
        <tbody>
          {rows.length === 0 ? (
            <tr>
              <td colSpan={3} style={{ ...cellStyle, color: 'var(--jx-color-fg-muted)', textAlign: 'center' }}>
                Нет пользователей
              </td>
            </tr>
          ) : (
            rows.map((user) => (
              <tr key={user.id}>
                <td style={cellStyle}>{user.name}</td>
                <td style={{ ...cellStyle, color: 'var(--jx-color-fg-muted)' }}>{user.role}</td>
                <td style={cellStyle}>
                  <span
                    style={{
                      display: 'inline-flex',
                      alignItems: 'center',
                      gap: 'var(--jx-space-2)',
                      padding: 'var(--jx-space-1) var(--jx-space-3)',
                      borderRadius: 'var(--jx-radius-full)',
                      fontSize: 'var(--jx-font-size-sm)',
                      color: user.active ? 'var(--jx-color-success-fg)' : 'var(--jx-color-fg-muted)',
                      background: user.active ? 'var(--jx-color-success-subtle)' : 'var(--jx-color-surface-muted)',
                    }}
                  >
                    <span
                      aria-hidden="true"
                      style={{
                        width: 'var(--jx-space-2)',
                        height: 'var(--jx-space-2)',
                        borderRadius: 'var(--jx-radius-full)',
                        background: 'currentColor',
                      }}
                    />
                    {user.active ? 'Активен' : 'Отключён'}
                  </span>
                </td>
              </tr>
            ))
          )}
        </tbody>
      </table>

      <nav
        aria-label="Навигация по страницам"
        style={{ display: 'flex', alignItems: 'center', justifyContent: 'flex-end', gap: 'var(--jx-space-3)' }}
      >
        <span aria-live="polite" style={{ color: 'var(--jx-color-fg-muted)', fontSize: 'var(--jx-font-size-sm)' }}>
          Страница {current + 1} из {pageCount}
        </span>
        <JxButton disabled={current === 0} onClick={() => setPage(current - 1)} aria-label="Предыдущая страница">
          Назад
        </JxButton>
        <JxButton
          disabled={current >= pageCount - 1}
          onClick={() => setPage(current + 1)}
          aria-label="Следующая страница"
        >
          Вперёд
        </JxButton>
      </nav>
    </div>
  );
}

export default UsersTable;

